class TemplateError(Exception):
    def __init__(self, message, line=1):
        super().__init__(message)
        self.line = line

# ── Undefined sentinel ──────────────────────────────────────────

class _Undefined:
    def __repr__(self):
        return "UNDEFINED"

UNDEFINED = _Undefined()

# ── Keyword set ────────────────────────────────────────────────

KEYWORDS = {'and', 'or', 'not', 'true', 'false', 'none', 'in'}

# ── Filter table: name → (arity, impl) ─────────────────────────

def _f_upper(v, _):
    return _render_value(v).upper()

def _f_lower(v, _):
    return _render_value(v).lower()

def _f_trim(v, _):
    return _render_value(v).strip(' \t\n\r')

def _f_length(v, _):
    if isinstance(v, str): return len(v)
    if isinstance(v, list): return len(v)
    if isinstance(v, dict): return len(v)
    return 0

def _f_first(v, _):
    if isinstance(v, list) and v: return v[0]
    return UNDEFINED

def _f_last(v, _):
    if isinstance(v, list) and v: return v[-1]
    return UNDEFINED

def _f_join(v, args, renderer=None):
    sep_val = renderer._eval(args[0])
    sep = _render_value(sep_val)
    if isinstance(v, list):
        return sep.join(_render_value(x) for x in v)
    return _render_value(v)

def _f_truncate(v, args, renderer=None):
    n_val = renderer._eval(args[0])
    text = _render_value(v)
    if isinstance(n_val, bool) or not isinstance(n_val, int):
        return text
    n = n_val
    if n < 3:
        n = 3
    if len(text) <= n:
        return text
    return text[:n - 3] + '...'

def _f_default(v, args, renderer=None):
    if v is UNDEFINED or v is None:
        return renderer._eval(args[0])
    return v

def _f_raw(v, _):
    return v

# name → (arity, needs_renderer, impl)
_FILTERS = {
    'upper':    (0, False, lambda v, _a, _r=None: _render_value(v).upper()),
    'lower':    (0, False, lambda v, _a, _r=None: _render_value(v).lower()),
    'trim':     (0, False, lambda v, _a, _r=None: _render_value(v).strip(' \t\n\r')),
    'length':   (0, False, lambda v, _a, _r=None: _f_length(v, None)),
    'first':    (0, False, lambda v, _a, _r=None: _f_first(v, None)),
    'last':     (0, False, lambda v, _a, _r=None: _f_last(v, None)),
    'raw':      (0, False, lambda v, _a, _r=None: v),
    'join':     (1, True,  _f_join),
    'truncate': (1, True,  _f_truncate),
    'default':  (1, True,  _f_default),
}

# ── Expression AST node classes ────────────────────────────────

class _Expr:
    pass

class _IntLit(_Expr):
    __slots__ = ('v',)
    def __init__(self, v): self.v = v

class _StrLit(_Expr):
    __slots__ = ('v',)
    def __init__(self, v): self.v = v

class _BoolLit(_Expr):
    __slots__ = ('v',)
    def __init__(self, v): self.v = v

class _NoneLit(_Expr):
    pass

class _Path(_Expr):
    __slots__ = ('name', 'segs')
    def __init__(self, name, segs): self.name, self.segs = name, segs

class _Paren(_Expr):
    __slots__ = ('e',)
    def __init__(self, e): self.e = e

class _Or(_Expr):
    __slots__ = ('l', 'r')
    def __init__(self, l, r): self.l, self.r = l, r

class _And(_Expr):
    __slots__ = ('l', 'r')
    def __init__(self, l, r): self.l, self.r = l, r

class _Not(_Expr):
    __slots__ = ('e',)
    def __init__(self, e): self.e = e

class _Cmp(_Expr):
    __slots__ = ('l', 'r', 'op')
    def __init__(self, l, r, op): self.l, self.r, self.op = l, r, op

class _FChain(_Expr):
    __slots__ = ('base', 'filters')
    def __init__(self, base, filters): self.base, self.filters = base, filters

# ── Template AST node classes ──────────────────────────────────

class _Text:
    __slots__ = ('text',)
    def __init__(self, text): self.text = text

class _Output:
    __slots__ = ('expr', 'line')
    def __init__(self, expr, line): self.expr, self.line = expr, line

class _If:
    __slots__ = ('branches', 'else_body', 'line')
    def __init__(self, branches, else_body, line):
        self.branches, self.else_body, self.line = branches, else_body, line

class _For:
    __slots__ = ('var', 'iter_expr', 'body', 'else_body', 'line')
    def __init__(self, var, iter_expr, body, else_body, line):
        self.var, self.iter_expr, self.body, self.else_body, self.line = var, iter_expr, body, else_body, line

class _Set:
    __slots__ = ('var', 'expr', 'line')
    def __init__(self, var, expr, line): self.var, self.expr, self.line = var, expr, line

# ── Helpers ────────────────────────────────────────────────────

def _truthy(v):
    if v is UNDEFINED or v is None: return False
    if isinstance(v, bool): return v
    if isinstance(v, int): return v != 0
    if isinstance(v, str): return len(v) > 0
    if isinstance(v, list): return len(v) > 0
    if isinstance(v, dict): return len(v) > 0
    return True

def _eq(a, b):
    if (a is UNDEFINED and b is None) or (a is None and b is UNDEFINED):
        return True
    def kind(v):
        if v is UNDEFINED: return 'u'
        if v is None: return 'n'
        if isinstance(v, bool): return 'b'
        if isinstance(v, int): return 'i'
        if isinstance(v, str): return 's'
        if isinstance(v, list): return 'l'
        if isinstance(v, dict): return 'd'
        return '?'
    if kind(a) != kind(b):
        return False
    if a is UNDEFINED or a is None:
        return True
    if isinstance(a, list):
        if len(a) != len(b): return False
        return all(_eq(x, y) for x, y in zip(a, b))
    if isinstance(a, dict):
        if len(a) != len(b): return False
        for k in a:
            if k not in b: return False
            if not _eq(a[k], b[k]): return False
        return True
    return a == b

def _render_value(v):
    if v is UNDEFINED or v is None: return ''
    if isinstance(v, bool): return 'true' if v else 'false'
    if isinstance(v, int): return str(v)
    if isinstance(v, str): return v
    if isinstance(v, list): return ', '.join(_render_value(x) for x in v)
    if isinstance(v, dict): return '[object]'
    return str(v)

def _escape(s):
    return s.replace('&', '&amp;').replace('<', '&lt;').replace('>', '&gt;').replace('"', '&quot;')

def _has_raw(expr):
    if isinstance(expr, _Or):  return _has_raw(expr.l) or _has_raw(expr.r)
    if isinstance(expr, _And): return _has_raw(expr.l) or _has_raw(expr.r)
    if isinstance(expr, _Not): return _has_raw(expr.e)
    if isinstance(expr, _Cmp): return _has_raw(expr.l) or _has_raw(expr.r)
    if isinstance(expr, _FChain):
        return any(n == 'raw' for n, _ in expr.filters)
    return False

def _line_of(template, pos):
    return template[:pos].count('\n') + 1

# ── Expression tokenizer ───────────────────────────────────────

def _tok_expr(src, line):
    toks = []
    i, n = 0, len(src)
    while i < n:
        c = src[i]
        if c in ' \t\n\r':
            i += 1; continue
        if src[i:i+2] == '==':
            toks.append(('eq', '==')); i += 2; continue
        if src[i:i+2] == '!=':
            toks.append(('neq', '!=')); i += 2; continue
        if c.isdigit():
            j = i
            while j < n and src[j].isdigit(): j += 1
            toks.append(('int', int(src[i:j]))); i = j; continue
        if c == '-' and i + 1 < n and src[i+1].isdigit():
            j = i + 1
            while j < n and src[j].isdigit(): j += 1
            toks.append(('int', -int(src[i+1:j]))); i = j; continue
        if c in '\'"':
            q = c; j = i + 1
            while j < n and src[j] != q: j += 1
            if j >= n:
                raise TemplateError("unclosed string literal", line)
            toks.append(('str', src[i+1:j])); i = j + 1; continue
        if c.isalpha() or c == '_':
            j = i
            while j < n and (src[j].isalnum() or src[j] == '_'): j += 1
            toks.append(('name', src[i:j])); i = j; continue
        if c == '.':
            if i + 1 < n and src[i+1].isdigit():
                j = i + 1
                while j < n and src[j].isdigit(): j += 1
                toks.append(('dotd', src[i+1:j])); i = j
            else:
                toks.append(('dot', '.')); i += 1
            continue
        if c == '|':
            toks.append(('pipe', '|')); i += 1; continue
        if c == '(':
            toks.append(('lparen', '(')); i += 1; continue
        if c == ')':
            toks.append(('rparen', ')')); i += 1; continue
        if c == '=':
            toks.append(('assign', '=')); i += 1; continue
        if c == ',':
            toks.append(('comma', ',')); i += 1; continue
        raise TemplateError(f"unexpected character '{c}' in expression", line)
    return toks

# ── Expression parser ──────────────────────────────────────────

def _parse_expr(t, p, line):
    return _parse_or(t, p, line)

def _parse_or(t, p, line):
    left, p = _parse_and(t, p, line)
    while p < len(t) and t[p][0] == 'name' and t[p][1] == 'or':
        p += 1
        right, p = _parse_and(t, p, line)
        left = _Or(left, right)
    return left, p

def _parse_and(t, p, line):
    left, p = _parse_not(t, p, line)
    while p < len(t) and t[p][0] == 'name' and t[p][1] == 'and':
        p += 1
        right, p = _parse_not(t, p, line)
        left = _And(left, right)
    return left, p

def _parse_not(t, p, line):
    if p < len(t) and t[p][0] == 'name' and t[p][1] == 'not':
        p += 1
        e, p = _parse_not(t, p, line)
        return _Not(e), p
    return _parse_cmp(t, p, line)

def _parse_cmp(t, p, line):
    left, p = _parse_fchain(t, p, line)
    if p < len(t) and t[p][0] in ('eq', 'neq'):
        op = '==' if t[p][0] == 'eq' else '!='
        p += 1
        right, p = _parse_fchain(t, p, line)
        return _Cmp(left, right, op), p
    return left, p

def _parse_fchain(t, p, line):
    base, p = _parse_primary(t, p, line)
    filters = []
    while p < len(t) and t[p][0] == 'pipe':
        p += 1
        if p >= len(t) or t[p][0] != 'name':
            raise TemplateError("expected filter name after '|'", line)
        fname = t[p][1]
        p += 1
        args = []
        if p < len(t) and t[p][0] == 'lparen':
            p += 1
            if p < len(t) and t[p][0] == 'rparen':
                p += 1
            else:
                while True:
                    a, p = _parse_expr(t, p, line)
                    args.append(a)
                    if p < len(t) and t[p][0] == 'comma':
                        p += 1
                        continue
                    break
                if p >= len(t) or t[p][0] != 'rparen':
                    raise TemplateError("expected ')'", line)
                p += 1
        # validate
        if fname not in _FILTERS:
            raise TemplateError(f"unknown filter '{fname}'", line)
        arity = _FILTERS[fname][0]
        if len(args) != arity:
            raise TemplateError(
                f"filter '{fname}' expects {arity} argument(s), got {len(args)}", line)
        filters.append((fname, args))
    return _FChain(base, filters), p

def _parse_primary(t, p, line):
    if p >= len(t):
        raise TemplateError("unexpected end of expression", line)
    tk = t[p]
    if tk[0] == 'int':
        return _IntLit(tk[1]), p + 1
    if tk[0] == 'str':
        return _StrLit(tk[1]), p + 1
    if tk[0] == 'name':
        w = tk[1]
        if w == 'true':  return _BoolLit(True), p + 1
        if w == 'false': return _BoolLit(False), p + 1
        if w == 'none':  return _NoneLit(), p + 1
        if w in KEYWORDS:
            raise TemplateError(f"unexpected keyword '{w}'", line)
        return _parse_path(t, p, line)
    if tk[0] == 'lparen':
        p += 1
        e, p = _parse_expr(t, p, line)
        if p >= len(t) or t[p][0] != 'rparen':
            raise TemplateError("expected ')'", line)
        return _Paren(e), p + 1
    raise TemplateError(f"unexpected token '{tk[1]}'", line)

def _parse_path(t, p, line):
    name = t[p][1]
    if name in KEYWORDS:
        raise TemplateError(f"keyword '{name}' cannot be a path name", line)
    p += 1
    segs = []
    while p < len(t):
        tk = t[p]
        if tk[0] == 'dotd':
            segs.append(tk[1]); p += 1
        elif tk[0] == 'dot':
            p += 1
            if p >= len(t):
                raise TemplateError("expected name or digits after '.'", line)
            if t[p][0] == 'name' and t[p][1] not in KEYWORDS:
                segs.append(t[p][1]); p += 1
            else:
                raise TemplateError("expected non-keyword name after '.'", line)
        else:
            break
    return _Path(name, segs), p

def _parse_output_expr(src, line):
    t = _tok_expr(src, line)
    if not t:
        raise TemplateError("empty expression", line)
    e, p = _parse_expr(t, 0, line)
    if p != len(t):
        raise TemplateError("unexpected tokens after expression", line)
    return e

# ── Block tag parser ───────────────────────────────────────────

def _parse_block(src, line):
    t = _tok_expr(src, line)
    if not t:
        raise TemplateError("empty block tag", line)
    if t[0][0] != 'name':
        raise TemplateError("expected block keyword", line)
    kw = t[0][1]

    if kw == 'if' or kw == 'elif':
        e, p = _parse_expr(t, 1, line)
        if p != len(t):
            raise TemplateError("unexpected tokens after expression", line)
        return kw, e, None

